def transform(grid):
    # Components of color 2 are 2x2 squares. Recolor in each contiguous diagonal
    # chain the squares at the two extremes of the chain.
    h,w=len(grid),len(grid[0])
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=2 or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); cells=[]
        while stack:
          x,y=stack.pop(); cells.append((x,y))
          for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            p=(x+dx,y+dy)
            if 0<=p[0]<h and 0<=p[1]<w and grid[p[0]][p[1]]==2 and p not in seen:
              seen.add(p); stack.append(p)
        comps.append(cells)
    # each 2x2 square is an independent object; diagonal adjacency groups are selected
    blocks=[]
    for cells in comps:
      rs=[x for x,y in cells]; cs=[y for x,y in cells]
      blocks.append((min(rs),min(cs),len(cells)))
    # chain diagonal blocks: recolor the end squares; rule inferred from demos
    # positions in demos indicate color marks squares with maximal/minimal row in connected diagonal motif
    out=[row[:] for row in grid]
    # Recolor squares with 2x2 component at row=0? no; use 2x2 components whose center shares diagonal neighbor
    starts=[]
    for r in range(h-1):
      for c in range(w-1):
        if all(grid[r+i][c+j]==2 for i in (0,1) for j in (0,1)):
          if (r==0 or not all(grid[r-1][c+j]==2 for j in (0,1))) and (c==0 or not all(grid[r+i][c-1]==2 for i in (0,1))): starts.append((r,c))
    # demos highlight blocks belonging to diagonal runs of 2x2 tiles, but leave isolated single blocks.
    for r,c in starts:
      if any(abs(r-a)==2 and abs(c-b)==2 for a,b in starts):
        for x in (r,r+1):
          for y in (c,c+1): out[x][y]=8
    return out
