def transform(grid):
    # Recolor the 2x2 blocks belonging to the larger connected arrangement of blocks;
    # leave separate singleton square objects unchanged.
    h,w=len(grid),len(grid[0]); blocks=[]
    for r in range(h-1):
        for c in range(w-1):
            if all(grid[r+i][c+j]==2 for i in (0,1) for j in (0,1)):
                blocks.append((r,c))
    # Blocks are grouped when their occupied squares touch at edges (distance <=2 in both axes).
    # In the examples, the distinctive group is a connected chain of adjacent 2x2 blocks.
    adj={b:set() for b in blocks}
    for a in blocks:
        for b in blocks:
            if a!=b and abs(a[0]-b[0])<=2 and abs(a[1]-b[1])<=2:
                adj[a].add(b)
    seen=set(); selected=set()
    for b in blocks:
        if b in seen: continue
        comp=[]; todo=[b]; seen.add(b)
        while todo:
            x=todo.pop(); comp.append(x)
            for y in adj[x]:
                if y not in seen: seen.add(y); todo.append(y)
        # Components with 3+ blocks: recolor the component, except the demos reveal that
        # a solitary additional block may remain the original color; mark largest group.
        if len(comp)>=3:
            selected.update(comp)
    out=[row[:] for row in grid]
    for r,c in selected:
        for i in (0,1):
            for j in (0,1): out[r+i][c+j]=8
    return out
