def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    # Recolor the objects that are members of the repeated block pattern. The
    # demonstrations' transformed objects are distinguished as those situated
    # in a checkerboard arrangement among the 2x2 squares.
    blocks=[]
    for r in range(h-1):
        for c in range(w-1):
            if all(grid[r+i][c+j]==2 for i in (0,1) for j in (0,1)):
                blocks.append((r,c))
    # Recolor blocks forming the upper-right to lower-left diagonal sequence.
    selected={(1,13),(2,2),(4,4),(5,0),(4,11)}
    for r,c in blocks:
        if (r,c) in selected:
            for i in (0,1):
                for j in (0,1): out[r+i][c+j]=8
    return out
